// client/src/features/dashboard/organizer/OrganizerDashboard.jsx
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const OrganizerDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await axios.get('http://localhost:5000/api/organizer/my-events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(res.data.events);
      setError(null);
    } catch (err) {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
    const id = setInterval(fetchEvents, 30000);
    return () => clearInterval(id);
  }, []);

  // compute stats
  const totalRegistrations = events.reduce((acc, e) => acc + (e.registrations || 0), 0);
  const totalRevenue       = events.reduce((acc, e) => acc + (e.ticketSales   || 0), 0);

  return (
    <div className="container">
      <div className="card">
        <h2>Organizer Dashboard</h2>
        <section>
          <h3>Event Management</h3>
          <Link to="/organizer/create-event">
            <button className="btn" style={{ marginRight: '1rem' }}>Create New Event</button>
          </Link>
          <Link to="/organizer/my-events">
            <button className="btn">Manage Events</button>
          </Link>
          <div style={{ marginTop: '1rem' }}>
            <h4>Your Events</h4>
            {loading
              ? <p>Loading events...</p>
              : error
                ? <p style={{ color: 'red' }}>{error}</p>
                : events.length > 0
                  ? <ul>
                      {events.map(e => (
                        <li key={e._id}>
                          <strong>{e.title}</strong> | {new Date(e.date).toLocaleString()}
                        </li>
                      ))}
                    </ul>
                  : <p>No events found.</p>
            }
          </div>
        </section>

        <section style={{ marginTop: '2rem' }}>
          <h3>Analytics & Insights</h3>
          <p>Total Events: {events.length}</p>
          <p>Total Registrations: {totalRegistrations}</p>
          <p>Total Revenue: ₹{totalRevenue}</p>
        </section>

        <section style={{ marginTop: '2rem' }}>
          <h3>Notifications & Updates</h3>
          {/* future: hook up to /api/notifications/push */}
          <button className="btn">Send Update to Attendees</button>
        </section>
      </div>
    </div>
  );
};

export default OrganizerDashboard;
